<section><p class="lead"><?php echo e(__('site.gallery_lead', [], $loc)); ?></p><?php if($media->isEmpty()): ?><p class="lead"><?php echo e(__('site.gallery_empty', [], $loc)); ?></p><?php else: ?><div class="gallery-grid"><?php $__currentLoopData = $media; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $item): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><figure class="gallery-item"><?php if($item->type === 'youtube'): ?><a class="gallery-media" href="<?php echo e($item->external_url); ?>" target="_blank" rel="noopener" aria-label="Voir <?php echo e($item->title); ?>"><img src="<?php echo e($item->thumbnail_url); ?>" alt="<?php echo e($item->title); ?>"><span class="gallery-play" aria-hidden="true">▶</span></a><?php elseif($item->type === 'google_drive'): ?><a class="gallery-media" href="<?php echo e($item->external_url); ?>" target="_blank" rel="noopener" aria-label="Ouvrir <?php echo e($item->title); ?>"><div style="height:100%;display:grid;place-items:center;color:#fff;font:600 13px Inter,sans-serif;letter-spacing:.08em;text-transform:uppercase;">Google Drive ↗</div></a><?php elseif($item->url): ?><a class="gallery-media" href="<?php echo e($item->url); ?>" data-lightbox-src="<?php echo e($item->url); ?>" data-lightbox-alt="<?php echo e($item->title); ?>" aria-label="Agrandir <?php echo e($item->title); ?>"><img src="<?php echo e($item->url); ?>" alt="<?php echo e($item->title); ?>"></a><?php endif; ?><figcaption class="gallery-caption"><h3><?php echo e($item->title); ?></h3><?php if($item->caption): ?><p><?php echo e($item->caption); ?></p><?php endif; ?></figcaption></figure><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></div><?php endif; ?></section><?php /**PATH C:\Users\erwan\OneDrive\Bureau\REFONTESITE\resources\views\resources\gallery.blade.php ENDPATH**/ ?>